L16_1[2] = L18_1
L17_1 = {}
L18_1 = "SI_SKIN_DESC_NKM_UNIT_C_ALT_YOO_JIN_RECITAL"
L19_1 = "她来自一个人吃人的世界。\n不遵守礼仪，甚至演奏音乐的那双手也非常粗糙。\n问我教了她什么？\n怎么说呢，音乐本来就是要述说本真的不是吗。\n\n<color=#ffd34c>你想让我认真一些？嗯……如果这是你想要的，老板，那我努力试试咯？</color>"
L17_1[1] = L18_1
