L17_1 = "SI_PF_TUTORIAL_TEXUTRE_UNIT_LIMITBREAK_3_DESC"
L18_1 = "职员可使用融合核心或相同职员单位进行<COLOR=#FFBC00>极限融合</COLOR>。每次进行\n<COLOR=#FFBC00>极限融合</COLOR>时，<COLOR=#FFBC00>最高等级增加2</COLOR>，<COLOR=#FFBC00>能力值增长率增加2%</COLOR>。\n<COLOR=#FFBC00>极限融合</COLOR><COLOR=#FFBC00>最多可进行五次</COLOR>。"
L16_1[1] = L17_1
L16_1[2] = L18_1
