L18_1[2] = L20_1
L19_1 = {}
L20_1 = "SI_SKIN_DESC_NKM_UNIT_C_FALLEN_ROSARIA_WEDDING"
L21_1 = "堕落之鹰侦探事务所现在正处于紧急状态。\n只因为老板任性地指定了新郎人选。\n当然，新郎的意愿从不在她的考虑范围之内。\n不过，偶尔她会以喜怒无常的决定来隐藏自己真正的内心。\n\n<color=#ffd34c>那么，现在开始举行世界上最激情的婚礼吧。</color>"
