L22_1 = "SI_SHOP_CASH_ITEM_POPUP_DESC_160365"
L23_1 = "大海背景\n沙滩\n海边的路边摊\n结果的椰子树 x 2\n遮阳伞和桌子\n遮阳伞和日光浴躺椅\n巴巴罗萨队长\n摩托艇\n休假中的机械甲\n野餐垫和食物盒\n海浪滔滔\n冲浪板放置架\n沙堡\n香蕉充气船\n安全员坐椅\n火烈鸟装饰\n沙滩排球场"
L21_1[1] = L22_1
L21_1[2] = L23_1
