L9_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_HORIZON_4_1_HM"
L10_1 = "怪物一直盘踞在人类的心灵深处。"
L8_1[1] = L9_1
L8_1[2] = L10_1
