L2_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_1_DESC_01"
L3_1 = "战略对抗战中，可以进行<COLOR=#FFBC00>非同步对战</COLOR>。可以与\n<COLOR=#FFBC00>对方的防御小队</COLOR>进行战斗。\n胜利时获得胜点，失败时失去胜点。"
L1_1[1] = L2_1
L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_4_DESC_01"
L4_1 = "参加战略对抗战时，必须<COLOR=#FFBC00>编辑防御小队</COLOR>。\n防御小队可抵挡其他公司的攻击，并受到增益和禁用&使用的影响。\n防御战胜利时，可获得<COLOR=#FFBC00>圣铠点数奖励</COLOR>。\n防御战失败时会减少胜点，但失败一定次数后不会继续减少。"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_ASYNC_4_TEXT_01_1"
L5_1 = "防御小队的部分单位将不对其他玩家公开。"
L3_1[1] = L4_1
L3_1[2] = L5_1
L4_1 = {}
L5_1 = "SI_PF_TUTORIAL_TEXUTRE_PVP_FRIENDLY_1_DESC"
