L35_1[2] = L37_1
L36_1 = {}
L37_1 = "SI_ITEM_MISC_DESC_IMI_ITEM_MISC_PACKAGE_GREMORY_BAR_1"
L38_1 = "为了给店里提供过帮助的顾客准备的特别礼券。\n可获得调酒师准备的多种商品。\n该物品将在活动过期时删除。"
