L19_1 = "SI_EPISODE_DESC_1_MAINSTREAM_EP_2"
L20_1 = "刘米娜请假来医院探病时，在市中心被卷入了一场侵蚀灾难。然而，灾难的背后似乎隐藏着其他阴谋。"
L18_1[1] = L19_1
L18_1[2] = L20_1
