L23_1[1] = L24_1
L23_1[2] = L25_1
L24_1 = {}
L25_1 = "SI_EPISODE_DESC_1_MAINSTREAM_EP_8"
L26_1 = "沃克上校带着他的新同事找上了约翰·梅森。无法友好相处的他们在搜寻新星级反应堆的过程中被卷入一场巨大的阴谋中。"
L24_1[1] = L25_1
L24_1[2] = L26_1
