L1_1[2] = L3_1
L2_1 = {}
L3_1 = "SI_PF_TUTORIAL_TEXUTRE_GUILD_DUNGEON_3_TITLE_DESC"
L4_1 = "每次净化行动都会向各个联盟成员提供5次团队副本入场次数。\n<COLOR=#FFBC00>可通过组合在竞技场获得的人造神器</COLOR>强化小队后投入到战场。\n首领根据自身的狂暴化阶段会拥有更高的体力、攻击力和防御力。"
L2_1[1] = L3_1
L2_1[2] = L4_1
L3_1 = {}
L4_1 = "SI_BOSS_DESC_S2_03"
L5_1 = "新兴派别团体的领袖，据推测应来自于埃克哈特超越学会的分支。\n该名人物因领导着一群自称为叛徒的追随者，无差别地袭击秘密隔离设施，回收圣湖碎片，目前处于被全世界通缉的状态。\n其使用的能力暂时无法识别，但应特别注意其手中挥舞的锁链。"
L3_1[1] = L4_1
L3_1[2] = L5_1
