L9_1[2] = L11_1
L10_1 = {}
L11_1 = "SI_UNIT_SKILL_DESC_CHAMBER_S_ENGINEER_SKILL_LV1"
L12_1 = "使用探测无人机随机收集可分解侵蚀物质的挥发性人造神器，强化除自身以外的友方单位。各种人造神器的收集概率相同，且根据人造神器的波动种类，对一定范围内除自身以外的友方单位赋予如下增益效果，持续12秒：（各波动对应的不同增益效果可叠加）\n\n【绿色波动】对侵蚀体伤害+30%\n【蓝色波动】对侵蚀体伤害+40%\n【红色波动】对侵蚀体伤害+50%"
