L18_1 = "SI_EPISODE_EPISODE_DESC_NKM_DUNGEON_EVENT_MEMORIAL_1_1"
L19_1 = "无论因黑色制服的沉重压力失眠多少次。\n即使累到倒下，少年也无法停下脚步。"
L17_1[1] = L18_1
