L23_1 = "AB_UI_UNIT_VOICE_NKM_UNIT_ALT_C_SEO_YOON_PR@AB_UI_UNIT_VOICE_NKM_UNIT_ALT_C_SEO_YOON_PR_LOBBY_CONNECT"
L24_1 = "那么，开始工作吧。"
